  1→"use client";
  2→
  3→/**
  4→ * React hook that manages the WebSocket connection to the thos relay server.
  5→ *
  6→ * Supports multiple concurrent agents. Each agent has its own status,
  7→ * message history, label, and tmux session name tracked in a Map keyed
  8→ * by agent ID. The `activeAgentId` determines which agent's chat is shown.
  9→ *
 10→ * ## Connection lifecycle
 11→ *
 12→ * 1. Connect to `ws://<host>:9900/browser`.
 13→ * 2. Server sends `agent_list` (sidebar metadata) + `task_list`. No
 14→ *    message histories are sent eagerly — this keeps the initial
 15→ *    payload small for fast loading on mobile networks.
 16→ * 3. `initialLoadDone` becomes true after `agent_list` arrives.
 17→ * 4. The first agent is auto-selected if nothing was selected.
 18→ *
 19→ * ## Lazy history loading
 20→ *
 21→ * Message histories are loaded on demand. When `activeAgentId` changes
 22→ * and the agent hasn't been loaded yet, the hook sends
 23→ * `{ type: "request_history", agentId }` and sets `historyLoading = true`.
 24→ * When the server responds with `message_history`, the agent's messages
 25→ * are populated and `historyLoading` becomes false.
 26→ *
 27→ * The `loadedAgents` Set tracks which agents have been fetched so that
 28→ * switching back to a previously viewed agent is instant.
 29→ *
 30→ * ## Resilience features
 31→ *
 32→ * - Handles `message_history` replay from server on demand.
 33→ * - Handles `cli_disconnected` / `cli_connected` events.
 34→ * - Deduplicates messages using a per-agent processed count.
 35→ * - Robust reconnection guard (clears previous timer before scheduling).
 36→ * - Strict mode safe (closingRef prevents spurious reconnects on unmount).
 37→ *
 38→ * ## Logging
 39→ *
 40→ * All WS events are logged with the `[thos-ws]` prefix. Filter by this
 41→ * in the browser console to debug connection and message delivery issues.
 42→ */
 43→
 44→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
 45→import type {
 46→  AgentInfo,
 47→  AgentStatus,
 48→  ChatMessage,
 49→  ClaudeAssistant,
 50→  ClaudeControlRequest,
 51→  ClaudeMessage,
 52→  ClaudeResult,
 53→  ClaudeSystemInit,
 54→  DirectoryEntry,
 55→  ServerMessage,
 56→  ServerMessageHistory,
 57→  ServerTaskList,
 58→  ServerTaskUpdated,
 59→  ServerTaskDeleted,
 60→  Task,
 61→  TaskPriority,
 62→  ToolCallInfo,
 63→  UserQuestion,
 64→  Workspace,
 65→} from "@/lib/types";
 66→import { playSound } from "@/lib/sound-engine";
 67→import { impactGenericLight000Sound } from "@/lib/impact-generic-light-000";
 68→import { impactGenericLight001Sound } from "@/lib/impact-generic-light-001";
 69→import { impactGenericLight002Sound } from "@/lib/impact-generic-light-002";
 70→import { impactGenericLight003Sound } from "@/lib/impact-generic-light-003";
 71→import { impactGenericLight004Sound } from "@/lib/impact-generic-light-004";
 72→
 73→/** Pool of impact sounds — a random one is picked for each code update. */
 74→const CODE_UPDATE_SOUNDS = [
 75→  impactGenericLight000Sound,
 76→  impactGenericLight001Sound,
 77→  impactGenericLight002Sound,
 78→  impactGenericLight003Sound,
 79→  impactGenericLight004Sound,
 80→];
 81→
 82→/** Tool names that modify code on disk. */
 83→const CODE_UPDATE_TOOLS = new Set(["Write", "Edit", "MultiEdit"]);
 84→
 85→/** Connect to the WS server on the same host the page was loaded from. */
 86→const WS_URL =
 87→  typeof window !== "undefined"
 88→    ? `ws://${window.location.hostname}:9900/browser`
 89→    : "ws://localhost:9900/browser";
 90→
 91→/** Per-agent client state. */
 92→export interface AgentClientState {
 93→  status: AgentStatus;
 94→  messages: ChatMessage[];
 95→  /** Raw Claude NDJSON messages for debug view. */
 96→  rawMessages: ClaudeMessage[];
 97→  label: string;
 98→  tmuxSession: string | null;
 99→  createdAt: number;
100→}
101→
102→/**
103→ * Extract displayable text from a Claude assistant message.
104→ * Content blocks may be text, tool_use, or tool_result — each is
105→ * handled defensively since the array structure can vary.
106→ */
107→function extractText(msg: ClaudeAssistant): string {
108→  const blocks = msg.message?.content;
109→  if (!blocks || !Array.isArray(blocks)) return "";
110→  return blocks
111→    .map((b) => {
112→      if (b.type === "text") return b.text;
113→      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
114→      if (b.type === "tool_result") {
115→        const c = (b as { content?: unknown }).content;
116→        return `[tool_result: ${typeof c === "string" ? c : JSON.stringify(c)}]`;
117→      }
118→      return "";
119→    })
120→    .filter(Boolean)
121→    .join("\n");
122→}
123→
124→/** Module-level counter for generating unique message IDs. */
125→let msgCounter = 0;
126→function nextId() {
127→  return `msg-${Date.now()}-${++msgCounter}`;
128→}
129→
130→/**
131→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
132→ * Used both for live messages and for replaying message_history.
133→ */
134→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
135→  if (relayMsg.type === "relay") {
136→    const msg = relayMsg.message;
137→
138→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
139→      const init = msg as ClaudeSystemInit;
140→      return {
141→        id: nextId(),
142→        role: "system",
143→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
144→        timestamp: Date.now(),
145→      };
146→    }
147→
148→    if (msg.type === "user") {
149→      const rawContent = (msg as { message?: { content?: unknown } }).message?.content ?? "";
150→      // Only render human-typed user messages (string content).
151→      // CLI tool_result messages have array content — these are internal
152→      // protocol messages and are only visible in the raw message viewer.
153→      if (typeof rawContent !== "string") return null;
154→      if (!rawContent.trim()) return null;
155→      return {
156→        id: nextId(),
157→        role: "user",
158→        content: rawContent,
159→        timestamp: Date.now(),
160→      };
161→    }
162→
163→    if (msg.type === "assistant") {
164→      const assistant = msg as ClaudeAssistant;
165→      const text = extractText(assistant);
166→      if (!text) return null;
167→
168→      const blocks = assistant.message?.content ?? [];
169→      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
170→
171→      // Build a map of tool_result blocks keyed by tool_use_id for preview extraction
172→      const resultMap = new Map<string, string>();
173→      for (const b of blocks) {
174→        if (b.type === "tool_result") {
175→          const tr = b as { tool_use_id?: string; content?: unknown };
176→          if (tr.tool_use_id) {
177→            const raw = typeof tr.content === "string" ? tr.content : JSON.stringify(tr.content ?? "");
178→            const firstLine = raw.split("\n")[0];
179→            resultMap.set(tr.tool_use_id, firstLine.length > 120 ? firstLine.slice(0, 117) + "..." : firstLine);
180→          }
181→        }
182→      }
183→
184→      const toolCalls: ToolCallInfo[] = blocks
185→        .filter((b) => b.type === "tool_use")
186→        .map((b) => ({
187→          name: (b as { name: string }).name,
188→          toolUseId: (b as { id: string }).id,
189→          resultPreview: resultMap.get((b as { id: string }).id),
190→        }));
191→      const isToolOnly = !hasText && toolCalls.length > 0;
192→
193→      return {
194→        id: nextId(),
195→        role: "assistant",
196→        content: text,
197→        timestamp: Date.now(),
198→        toolCalls,
199→        isToolOnly,
200→      };
201→    }
202→
203→    if (msg.type === "result") {
204→      const result = msg as ClaudeResult;
205→      const summary = result.is_error
206→        ? `Error: ${result.error}`
207→        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
208→      return {
209→        id: nextId(),
210→        role: "system",
211→        content: summary,
212→        timestamp: Date.now(),
213→      };
214→    }
215→
216→    if (msg.type === "control_request") {
217→      const cr = msg as ClaudeControlRequest;
218→
219→      // AskUserQuestion gets its own UI instead of generic Allow/Deny
220→      if (cr.request.tool_name === "AskUserQuestion") {
221→        const input = cr.request.input as { questions?: UserQuestion[] };
222→        const questions = Array.isArray(input.questions) ? input.questions : [];
223→        return {
224→          id: nextId(),
225→          role: "system",
226→          content: "Question from Claude",
227→          timestamp: Date.now(),
228→          userQuestion: {
229→            requestId: cr.request_id,
230→            questions,
231→          },
232→        };
233→      }
234→
235→      return {
236→        id: nextId(),
237→        role: "system",
238→        content: `Tool approval requested: ${cr.request.tool_name}`,
239→        timestamp: Date.now(),
240→        controlRequest: {
241→          id: cr.request_id,
242→          tool_name: cr.request.tool_name,
243→          input: cr.request.input,
244→          description: cr.request.description,
245→        },
246→      };
247→    }
248→  }
249→
250→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
251→    return {
252→      id: nextId(),
253→      role: "system",
254→      content: `Error: ${relayMsg.error}`,
255→      timestamp: Date.now(),
256→    };
257→  }
258→
259→  return null;
260→}
