175→            </span>
176→          </div>
177→        ) : showRaw ? (
178→          rawMessages.length === 0 ? (
179→            <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
180→              No raw messages yet
181→            </div>
182→          ) : (
183→            <div className="space-y-1">
184→              {rawMessages.map((msg, i) => (
185→                <RawMessage key={i} message={msg} index={i} />
