267→export function useWebSocket() {
268→  const wsRef = useRef<WebSocket | null>(null);
269→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
270→  /** Set to true during cleanup to prevent onclose from scheduling reconnects. */
271→  const closingRef = useRef(false);
272→  const [connected, setConnected] = useState(false);
273→  /** True once we've received the initial agent_list from the server. */
274→  const [initialLoadDone, setInitialLoadDone] = useState(false);
275→
276→  // Multi-agent state
277→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
278→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
279→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
280→
281→  // Task state
282→  const [tasks, setTasks] = useState<Task[]>([]);
283→
284→  // Workspace state
285→  const [workspaces, setWorkspaces] = useState<Workspace[]>([]);
286→  const [activeWorkspaceId, setActiveWorkspaceIdState] = useState<string | null>(null);
287→  const [directoryListing, setDirectoryListing] = useState<{ path: string; entries: DirectoryEntry[] } | null>(null);
288→
289→  // Per-agent deduplication: track count of processed messages per agent
290→  // to avoid duplicating messages already in local state during history replay.
291→  const processedCountRef = useRef<Map<string, number>>(new Map());
292→
293→  // Track which agents have had their history loaded (lazy loading).
294→  const [loadedAgents, setLoadedAgents] = useState<Set<string>>(new Set());
295→
296→  /** Immutably update a single agent's state in the Map. */
297→  const updateAgent = useCallback(
298→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
299→      setAgents((prev) => {
300→        const existing = prev.get(agentId);
301→        if (!existing) return prev;
302→        const next = new Map(prev);
303→        next.set(agentId, updater(existing));
304→        return next;
305→      });
306→    },
307→    []
308→  );
309→
310→  const connect = useCallback(() => {
311→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
312→    if (wsRef.current) {
313→      wsRef.current.close();
314→      wsRef.current = null;
315→    }
316→
317→    // Reset dedup counts on new connection — server will send fresh history
318→    processedCountRef.current.clear();
319→    setInitialLoadDone(false);
320→    setLoadedAgents(new Set());
321→
322→    log("connecting to", WS_URL);
323→    const ws = new WebSocket(WS_URL);
324→    wsRef.current = ws;
325→
326→    ws.onopen = () => {
327→      log("connected");
328→      setConnected(true);
329→    };
330→
331→    ws.onclose = () => {
332→      log("disconnected, closingRef =", closingRef.current);
333→      setConnected(false);
334→      wsRef.current = null;
335→      // Don't reconnect if the close was triggered by cleanup (e.g. strict mode unmount)
336→      if (closingRef.current) return;
337→      // Reconnection guard: clear any existing timer before scheduling
338→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
339→      log("scheduling reconnect in 2s");
340→      reconnectTimer.current = setTimeout(() => connect(), 2000);
341→    };
342→
343→    ws.onerror = (e) => {
344→      log("error", e);
345→      // onclose will fire after onerror, which triggers reconnect
346→    };
347→
348→    ws.onmessage = (event) => {
349→      let data: ServerMessage;
350→      try {
351→        data = JSON.parse(event.data as string);
352→      } catch {
353→        return;
354→      }
355→
356→      log("←", data.type, "agentId" in data ? (data as { agentId: string }).agentId : "");
357→
358→      // ── workspace_list: full workspace list from server ──
359→      if (data.type === "workspace_list") {
360→        const wsList = (data as { workspaces: Workspace[] }).workspaces;
361→        log("workspace_list:", wsList.length, "workspaces");
362→        setWorkspaces(wsList);
363→        return;
364→      }
365→
366→      // ── directory_listing: response to browse_directory ──
367→      if (data.type === "directory_listing") {
368→        const listing = data as { path: string; entries: DirectoryEntry[] };
369→        log("directory_listing:", listing.path, listing.entries.length, "entries");
370→        setDirectoryListing({ path: listing.path, entries: listing.entries });
371→        return;
372→      }
373→
374→      // ── task_list: full task list from server ──
375→      if (data.type === "task_list") {
376→        log("task_list:", (data as ServerTaskList).tasks.length, "tasks");
377→        setTasks((data as ServerTaskList).tasks);
378→        return;
379→      }
380→
381→      // ── task_updated: single task changed ──
382→      if (data.type === "task_updated") {
383→        const updated = (data as ServerTaskUpdated).task;
384→        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
385→        return;
386→      }
387→
388→      // ── task_deleted: remove task ──
389→      if (data.type === "task_deleted") {
390→        const deletedId = (data as ServerTaskDeleted).taskId;
391→        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
392→        return;
393→      }
394→
395→      // ── message_history: replay full history from server ──
396→      if (data.type === "message_history") {
397→        const historyMsg = data as ServerMessageHistory;
398→        const agentId = historyMsg.agentId;
399→        const serverMessages = historyMsg.messages;
400→        log("message_history:", agentId, serverMessages.length, "raw msgs");
401→
402→        // Convert all server messages to ChatMessages + extract raw Claude messages
403→        const chatMessages: ChatMessage[] = [];
404→        const rawMessages: ClaudeMessage[] = [];
405→        for (const sm of serverMessages) {
406→          if (sm.type === "relay") {
407→            rawMessages.push(sm.message);
408→          }
409→          const cm = relayChatMessage(agentId, sm);
410→          if (cm) chatMessages.push(cm);
411→        }
412→        log("message_history:", agentId, "→", chatMessages.length, "chat msgs,", rawMessages.length, "raw");
413→
414→        // Always replace local messages with server history (source of truth).
415→        setAgents((prev) => {
416→          const existing = prev.get(agentId);
417→          if (!existing) {
418→            log("message_history:", agentId, "agent not in map yet, creating");
419→            const next = new Map(prev);
420→            next.set(agentId, {
421→              status: "idle",
422→              messages: chatMessages,
423→              rawMessages,
424→              label: "",
425→              tmuxSession: null,
426→              createdAt: 0,
427→            });
428→            return next;
429→          }
430→          const next = new Map(prev);
431→          next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
432→          return next;
433→        });
434→
435→        processedCountRef.current.set(agentId, chatMessages.length);
436→        setLoadedAgents((prev) => {
437→          if (prev.has(agentId)) return prev;
438→          const next = new Set(prev);
439→          next.add(agentId);
440→          return next;
441→        });
442→        return;
443→      }
444→
445→      // ── history_cleared: wipe local messages for this agent ──
446→      if (data.type === "history_cleared") {
447→        updateAgent(data.agentId, (prev) => ({
448→          ...prev,
449→          messages: [],
450→          rawMessages: [],
451→        }));
452→        processedCountRef.current.set(data.agentId, 0);
453→        return;
454→      }
455→
456→      // ── cli_disconnected: show system message ──
457→      if (data.type === "cli_disconnected") {
458→        updateAgent(data.agentId, (prev) => ({
459→          ...prev,
460→          messages: [
461→            ...prev.messages,
462→            {
463→              id: nextId(),
464→              role: "system",
465→              content: "CLI session ended",
466→              timestamp: Date.now(),
467→            },
468→          ],
469→        }));
470→        return;
471→      }
472→
473→      // ── cli_connected: show system message ──
474→      if (data.type === "cli_connected") {
475→        updateAgent(data.agentId, (prev) => ({
476→          ...prev,
477→          messages: [
478→            ...prev.messages,
479→            {
480→              id: nextId(),
481→              role: "system",
482→              content: "CLI reconnected",
483→              timestamp: Date.now(),
484→            },
485→          ],
486→        }));
487→        return;
488→      }
489→
490→      // ── agent_list: reconcile sidebar state from server ──
491→      if (data.type === "agent_list") {
492→        const serverAgents = data.agents as AgentInfo[];
493→        log("agent_list:", serverAgents.length, "agents:", serverAgents.map((a) => `${a.agentId}(${a.status})`).join(", "));
494→        setAgents((prev) => {
495→          const next = new Map(prev);
496→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
497→
498→          // Update or add agents from server
499→          for (const info of serverAgents) {
500→            const existing = next.get(info.agentId);
501→            if (existing) {
502→              next.set(info.agentId, {
503→                ...existing,
504→                status: info.status,
505→                tmuxSession: info.tmuxSession,
506→                label: info.label,
507→              });
508→            } else {
509→              next.set(info.agentId, {
510→                status: info.status,
511→                messages: [],
512→                rawMessages: [],
513→                label: info.label,
514→                tmuxSession: info.tmuxSession,
515→                createdAt: info.createdAt,
516→              });
517→            }
518→          }
519→
520→          // Remove agents no longer on the server
521→          for (const id of next.keys()) {
522→            if (!serverIds.has(id)) {
523→              next.delete(id);
524→            }
525→          }
526→
527→          return next;
528→        });
529→        setAgentOrder(serverAgents.map((a) => a.agentId));
530→        setInitialLoadDone(true);
531→
532→        // Auto-select the first agent on initial load when nothing is selected
533→        setActiveAgentId((prev) => {
534→          if (prev !== null) return prev;
535→          if (serverAgents.length === 0) return null;
536→          return serverAgents[0].agentId;
537→        });
538→        return;
539→      }
540→
541→      // ── spawned: auto-select the newly created agent ──
542→      if (data.type === "spawned") {
543→        setActiveAgentId(data.agentId);
544→        return;
545→      }
546→
547→      // ── status: update a specific agent's status ──
548→      if (data.type === "status") {
549→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
550→        return;
551→      }
552→
553→      // ── error: append to agent's message list ──
554→      if (data.type === "error") {
555→        updateAgent(data.agentId, (prev) => ({
556→          ...prev,
557→          messages: [
558→            ...prev.messages,
559→            {
560→              id: nextId(),
561→              role: "system",
562→              content: `Error: ${data.error}`,
563→              timestamp: Date.now(),
564→            },
565→          ],
566→        }));
567→        // Track processed count for dedup
568→        processedCountRef.current.set(
569→          data.agentId,
570→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
571→        );
572→        return;
573→      }
574→
575→      // ── relay: append claude message to agent's history ──
576→      if (data.type === "relay") {
577→        const agentId = data.agentId;
578→        const rawMsg = data.message;
579→        const chatMsg = relayChatMessage(agentId, data);
580→
581→        // Play impact SFX when a code-modifying tool completes
582→        if (chatMsg?.toolCalls?.some((tc) => CODE_UPDATE_TOOLS.has(tc.name))) {
583→          const sfx = CODE_UPDATE_SOUNDS[Math.floor(Math.random() * CODE_UPDATE_SOUNDS.length)];
584→          playSound(sfx.dataUri, { volume: 0.4 });
585→        }
586→
587→        updateAgent(agentId, (prev) => ({
588→          ...prev,
589→          rawMessages: [...prev.rawMessages, rawMsg],
590→          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
591→        }));
592→        if (chatMsg) {
593→          // Track processed count for dedup
594→          processedCountRef.current.set(
595→            agentId,
596→            (processedCountRef.current.get(agentId) ?? 0) + 1
597→          );
598→        }
599→        return;
600→      }
601→    };
602→  }, [updateAgent]);
603→
604→  useEffect(() => {
605→    closingRef.current = false;
