 38→  onSpawnAgent,
 39→  onRespondToControl,
 40→  onRespondToUserQuestion,
 41→  onClearHistory,
 42→  showTasks,
 43→  onToggleTasks,
 44→  onToggleSidebar,
 45→}: {
 46→  connected: boolean;
 47→  loading?: boolean;
 48→  status: AgentStatus;
 49→  messages: ChatMessage[];
 50→  rawMessages: ClaudeMessage[];
 51→  onSendMessage: (content: string) => void;
 52→  onSpawnAgent: (prompt: string) => void;
 53→  onRespondToControl: (requestId: string, allow: boolean) => void;
 54→  onRespondToUserQuestion: (requestId: string, answers: Record<string, string>) => void;
 55→  onClearHistory?: () => void;
 56→  showTasks?: boolean;
 57→  onToggleTasks?: () => void;
 58→  onToggleSidebar?: () => void;
 59→}) {
 60→  const [input, setInput] = useState("");
 61→  const [showRaw, setShowRaw] = useState(false);
 62→  const [showSlashMenu, setShowSlashMenu] = useState(false);
 63→  const [slashQuery, setSlashQuery] = useState("");
 64→  const [slashHighlight, setSlashHighlight] = useState(0);
 65→  const scrollRef = useRef<HTMLDivElement>(null);
 66→  const inputRef = useRef<HTMLInputElement>(null);
 67→
 68→  useEffect(() => {
 69→    scrollRef.current?.scrollTo({
 70→      top: scrollRef.current.scrollHeight,
 71→      behavior: "smooth",
 72→    });
 73→  }, [messages, rawMessages, showRaw]);
 74→
 75→  const displayItems = useMemo(() => condenseMessages(messages), [messages]);
 76→  const isActive = status === "connected" || status === "thinking";
 77→  const isArchived = status === "done" || status === "disconnected" || status === "error";
 78→
 79→  function handleSubmit(e: React.FormEvent) {
 80→    e.preventDefault();
 81→    const trimmed = input.trim();
 82→    if (!trimmed) return;
 83→
 84→    if (isActive) {
 85→      onSendMessage(trimmed);
 86→    } else {
 87→      onSpawnAgent(trimmed);
 88→    }
 89→    setInput("");
 90→    setShowSlashMenu(false);
 91→  }
 92→
 93→  function handleInputChange(e: React.ChangeEvent<HTMLInputElement>) {
 94→    const value = e.target.value;
 95→    setInput(value);
 96→
 97→    if (value.startsWith("/")) {
 98→      setShowSlashMenu(true);
 99→      setSlashQuery(value.slice(1));
100→      setSlashHighlight(0);
101→    } else {
102→      setShowSlashMenu(false);
103→      setSlashQuery("");
104→    }
105→  }
106→
107→  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
108→    if (!showSlashMenu) return;
109→    const filtered = filterCommands(slashQuery);
110→    if (filtered.length === 0) return;
111→
112→    if (e.key === "ArrowDown") {
113→      e.preventDefault();
114→      setSlashHighlight((i) => (i + 1) % filtered.length);
115→    } else if (e.key === "ArrowUp") {
116→      e.preventDefault();
117→      setSlashHighlight((i) => (i - 1 + filtered.length) % filtered.length);
118→    } else if (e.key === "Enter") {
119→      e.preventDefault();
120→      handleCommandSelect(filtered[slashHighlight]);
121→    } else if (e.key === "Escape") {
122→      e.preventDefault();
123→      setShowSlashMenu(false);
124→    } else if (e.key === "Tab") {
125→      e.preventDefault();
126→      setInput(`/${filtered[slashHighlight].name} `);
127→      setShowSlashMenu(false);
128→    }
129→  }
130→
131→  function handleCommandSelect(command: SlashCommand) {
132→    setShowSlashMenu(false);
133→    setSlashQuery("");
134→    setInput("");
135→
136→    if (command.clientSide) {
137→      if (command.name === "clear") {
138→        onClearHistory?.();
139→      }
140→      return;
141→    }
142→
143→    const commandText = `/${command.name}`;
144→    if (isActive) {
145→      onSendMessage(commandText);
146→    } else {
147→      onSpawnAgent(commandText);
148→    }
149→  }
150→
151→  return (
152→    <div className="flex h-full flex-col">
153→      <StatusBar
154→        connected={connected}
155→        status={status}
156→        showRaw={showRaw}
157→        onToggleRaw={() => setShowRaw((v) => !v)}
158→        showTasks={showTasks}
159→        onToggleTasks={onToggleTasks}
160→        onToggleSidebar={onToggleSidebar}
161→      />
162→
163→      <AgentSummary rawMessages={rawMessages} />
164→
165→      <div ref={scrollRef} className="flex-1 overflow-y-auto p-2 md:p-4 space-y-2">
166→        {loading ? (
167→          <div className="flex h-full flex-col items-center justify-center gap-3">
168→            <div className="flex gap-1">
169→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse" />
170→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:150ms]" />
171→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:300ms]" />
172→            </div>
173→            <span className="text-xs text-muted-foreground">
174→              {connected ? "Loading messages..." : "Connecting..."}
175→            </span>
176→          </div>
177→        ) : showRaw ? (
178→          rawMessages.length === 0 ? (
179→            <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
180→              No raw messages yet
181→            </div>
182→          ) : (
183→            <div className="space-y-1">
184→              {rawMessages.map((msg, i) => (
185→                <RawMessage key={i} message={msg} index={i} />
186→              ))}
187→            </div>
188→          )
189→        ) : (
190→          <>
191→            {messages.length === 0 && (
192→              <div className="flex h-full flex-col items-center justify-center gap-4 text-muted-foreground">
193→                <Terminal className="size-10 opacity-30" />
194→                <div className="text-center">
195→                  <p className="text-sm font-medium text-foreground/80">No agent selected</p>
196→                  <p className="mt-1 text-xs">Type a prompt below to spawn a Claude agent</p>
197→                </div>
198→                <div className="mt-2 grid grid-cols-2 gap-3 text-[11px]">
199→                  <div className="flex items-start gap-2 rounded-lg border p-3">
200→                    <MessageSquare className="mt-0.5 size-3.5 shrink-0 text-primary" />
201→                    <div>
202→                      <p className="font-medium text-foreground/80">Chat</p>
203→                      <p className="mt-0.5">Send prompts and review tool calls in real time</p>
204→                    </div>
205→                  </div>
206→                  <div className="flex items-start gap-2 rounded-lg border p-3">
207→                    <ListTodo className="mt-0.5 size-3.5 shrink-0 text-primary" />
208→                    <div>
209→                      <p className="font-medium text-foreground/80">Tasks</p>
210→                      <p className="mt-0.5">Track work with a kanban board and delegate to agents</p>
211→                    </div>
212→                  </div>
213→                </div>
214→              </div>
215→            )}
216→            {displayItems.map((item) => {
217→              if (item.kind === "condensed") {
218→                return <CondensedToolGroup key={item.id} group={item} />;
219→              }
220→              const msg = item.message;
221→              return msg.userQuestion ? (
222→                <UserQuestion
223→                  key={msg.id}
224→                  message={msg}
225→                  onRespond={onRespondToUserQuestion}
226→                />
227→              ) : msg.controlRequest ? (
228→                <ControlRequest
229→                  key={msg.id}
230→                  message={msg}
231→                  onRespond={onRespondToControl}
232→                />
233→              ) : (
234→                <Message key={msg.id} message={msg} />
235→              );
236→            })}
237→          </>
238→        )}
239→      </div>
240→
241→      {isArchived && messages.length > 0 ? (
242→        <div className="border-t px-4 py-2 text-center text-xs text-muted-foreground">
243→          This session has ended
244→        </div>
245→      ) : (
246→        <form
247→          onSubmit={handleSubmit}
248→          className="relative flex gap-2 border-t px-2 py-2 md:px-4 md:py-3"
249→        >
250→          {showSlashMenu && (
251→            <SlashCommandMenu
252→              query={slashQuery}
253→              highlightedIndex={slashHighlight}
254→              onSelect={handleCommandSelect}
255→              onHighlight={setSlashHighlight}
256→            />
257→          )}
258→          <input
259→            ref={inputRef}
260→            type="text"
261→            value={input}
262→            onChange={handleInputChange}
263→            onKeyDown={handleKeyDown}
264→            placeholder={isActive ? "Send a follow-up..." : "Enter a prompt to spawn agent..."}
265→            className="flex-1 rounded-md border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring"
266→          />
267→          <Button type="submit" disabled={!connected || !input.trim()}>
268→            {isActive ? "Send" : "Spawn"}
269→          </Button>
270→        </form>
271→      )}
272→    </div>
273→  );
274→}
