 71→
 72→  // Derive initial path from first workspace or fallback to "/"
 73→  const initialBrowsePath = workspaces.length > 0 ? workspaces[0].cwd : "/";
 74→
 75→  // Connection status toasts (skip initial connection)
 76→  const hasConnectedRef = useRef(false);
 77→  useEffect(() => {
 78→    if (connected) {
 79→      if (hasConnectedRef.current) {
 80→        toast.success("Reconnected");
 81→      }
 82→      hasConnectedRef.current = true;
 83→    } else if (hasConnectedRef.current) {
 84→      toast.error("Connection lost");
 85→    }
 86→  }, [connected]);
 87→
 88→  useEffect(() => {
 89→    document.title = "thos — dashboard";
 90→  }, []);
 91→
 92→  return (
 93→    <div className="relative flex h-dvh overflow-hidden">
 94→      {/* Sidebar backdrop (mobile only) */}
 95→      {sidebarOpen && (
 96→        <div
 97→          className="fixed inset-0 z-40 bg-black/50 md:hidden"
 98→          onClick={() => setSidebarOpen(false)}
 99→        />
100→      )}
101→
102→      {/* Sidebar drawer */}
103→      <div
104→        className={cn(
105→          "fixed inset-y-0 left-0 z-50 w-56 transition-transform duration-200 ease-in-out md:relative md:z-auto md:translate-x-0 md:transition-none",
106→          sidebarOpen ? "translate-x-0" : "-translate-x-full"
107→        )}
108→      >
109→        <AgentSidebar
110→          agents={agents}
111→          agentOrder={agentOrder}
112→          activeAgentId={activeAgentId}
113→          loading={!initialLoadDone}
114→          onSelect={(id) => {
115→            setActiveAgentId(id);
116→            setSidebarOpen(false);
117→          }}
118→          onNewAgent={() => {
119→            setActiveAgentId(null);
120→            setSidebarOpen(false);
121→          }}
122→          onKill={killAgent}
123→          onDelete={deleteAgent}
124→          onRename={renameAgent}
125→          onClearHistory={clearHistory}
126→          workspaces={workspaces}
127→          activeWorkspaceId={activeWorkspaceId}
128→          onSelectWorkspace={setActiveWorkspaceId}
129→          onRenameWorkspace={renameWorkspace}
130→          onDeleteWorkspace={deleteWorkspace}
131→          onOpenFolder={() => setFolderBrowserOpen(true)}
132→        />
133→      </div>
134→
135→      {/* Main chat area (hidden in board mode) */}
136→      <div className={cn("flex min-w-0 flex-1 flex-col", taskView === "board" && "hidden")}>
137→        <Chat
138→          connected={connected}
139→          loading={!initialLoadDone || historyLoading}
140→          status={activeStatus}
141→          messages={activeMessages}
142→          rawMessages={activeRawMessages}
143→          onSendMessage={sendMessage}
144→          onSpawnAgent={spawnAgent}
145→          onRespondToControl={respondToControl}
146→          onRespondToUserQuestion={respondToUserQuestion}
147→          onClearHistory={() => { if (activeAgentId) clearHistory(activeAgentId); }}
148→          showTasks={taskView !== "hidden"}
149→          onToggleTasks={() => setTaskView((v) => (v === "hidden" ? "list" : "hidden"))}
150→          onToggleSidebar={() => setSidebarOpen((v) => !v)}
151→        />
152→      </div>
153→
154→      {/* Task panel backdrop (mobile only) */}
155→      {taskView !== "hidden" && (
156→        <div
157→          className="fixed inset-0 z-40 bg-black/50 md:hidden"
158→          onClick={() => setTaskView("hidden")}
159→        />
160→      )}
161→
162→      {/* Task panel drawer */}
163→      {taskView !== "hidden" && (
164→        <div
165→          className={cn(
166→            "fixed inset-y-0 right-0 z-50 border-l bg-background flex flex-col min-w-0 md:relative md:z-auto",
167→            taskView === "board"
168→              ? "w-full max-w-none"
169→              : "w-80 max-w-[calc(100vw-3rem)] md:max-w-none"
170→          )}
171→        >
172→          <TaskPanel
173→            tasks={tasks}
174→            mode={taskView}
175→            onModeChange={(mode) => setTaskView(mode)}
176→            onCreateTask={createTask}
177→            onUpdateTask={updateTask}
178→            onDeleteTask={deleteTask}
179→            onDelegateTask={delegateTask}
180→            onSelectAgent={(agentId) => {
181→              setActiveAgentId(agentId);
182→            }}
183→            onClose={() => setTaskView("hidden")}
184→          />
185→        </div>
186→      )}
187→
188→      {/* Folder browser modal */}
189→      <FolderBrowser
190→        open={folderBrowserOpen}
191→        onClose={() => setFolderBrowserOpen(false)}
192→        directoryListing={directoryListing}
193→        onBrowse={browseDirectory}
194→        onCreate={(name, cwd) => {
195→          createWorkspace(name, cwd);
196→          setFolderBrowserOpen(false);
197→        }}
198→        initialPath={initialBrowsePath}
199→      />
200→
201→      <Toaster />
202→    </div>
203→  );
204→}
