 54→        </span>
 55→      </button>
 56→      {expanded && (
 57→        <div className="px-2 pb-2 space-y-2">
 58→          {group.diffs.map((tc, i) => (
 59→            <DiffViewer key={tc.toolUseId ?? i} toolCall={tc} />
 60→          ))}
 61→        </div>
 62→      )}
 63→    </div>
 64→  );
 65→}
