 46→  AgentInfo,
 47→  AgentStatus,
 48→  ChatMessage,
 49→  ClaudeAssistant,
 50→  ClaudeControlRequest,
 51→  ClaudeMessage,
 52→  ClaudeResult,
 53→  ClaudeSystemInit,
 54→  DirectoryEntry,
 55→  ServerMessage,
 56→  ServerMessageHistory,
 57→  ServerTaskList,
 58→  ServerTaskUpdated,
 59→  ServerTaskDeleted,
 60→  Task,
 61→  TaskPriority,
 62→  ToolCallInfo,
 63→  UserQuestion,
