  1→"use client";
  2→
  3→/**
  4→ * Main chat interface for the thos dashboard.
  5→ *
  6→ * Composes {@link StatusBar}, a scrollable message list ({@link Message}
  7→ * and {@link ControlRequest} cards), and an input bar. The submit button
  8→ * text toggles between "Spawn" (when idle/done) and "Send" (when an
  9→ * agent session is active). Auto-scrolls on new messages.
 10→ *
 11→ * A toggle in the top-right switches between the processed chat view
 12→ * and a raw JSON view of all Claude NDJSON messages.
 13→ *
 14→ * Receives all data and callbacks via props — the parent page component
 15→ * owns the WebSocket hook and orchestrates multiple agents.
 16→ */
 17→
 18→import { useEffect, useMemo, useRef, useState } from "react";
 19→import { ListTodo, MessageSquare, Terminal } from "lucide-react";
 20→import type { AgentStatus, ChatMessage, ClaudeMessage } from "@/lib/types";
 21→import { condenseMessages } from "@/lib/condense-messages";
 22→import { StatusBar } from "./status-bar";
 23→import { AgentSummary } from "./agent-summary";
 24→import { Message } from "./message";
 25→import { ControlRequest } from "./control-request";
 26→import { UserQuestion } from "./user-question";
 27→import { CondensedToolGroup } from "./condensed-tool-group";
 28→import { SlashCommandMenu, filterCommands, type SlashCommand } from "./slash-command-menu";
 29→import { Button } from "@/components/ui/button";
 30→
 31→export function Chat({
 32→  connected,
 33→  loading,
 34→  status,
 35→  messages,
 36→  rawMessages,
 37→  onSendMessage,
 38→  onSpawnAgent,
 39→  onRespondToControl,
 40→  onRespondToUserQuestion,
 41→  onClearHistory,
 42→  showTasks,
 43→  onToggleTasks,
 44→  showDiffs,
 45→  onToggleDiffs,
 46→  onToggleSidebar,
 47→  onOpenSfxSettings,
 48→}: {
 49→  connected: boolean;
 50→  loading?: boolean;
 51→  status: AgentStatus;
 52→  messages: ChatMessage[];
 53→  rawMessages: ClaudeMessage[];
 54→  onSendMessage: (content: string) => void;
 55→  onSpawnAgent: (prompt: string) => void;
 56→  onRespondToControl: (requestId: string, allow: boolean) => void;
 57→  onRespondToUserQuestion: (requestId: string, answers: Record<string, string>) => void;
 58→  onClearHistory?: () => void;
 59→  showTasks?: boolean;
 60→  onToggleTasks?: () => void;
 61→  showDiffs?: boolean;
 62→  onToggleDiffs?: () => void;
 63→  onToggleSidebar?: () => void;
 64→  onOpenSfxSettings?: () => void;
 65→}) {
 66→  const [input, setInput] = useState("");
 67→  const [showRaw, setShowRaw] = useState(false);
 68→  const [showSlashMenu, setShowSlashMenu] = useState(false);
 69→  const [slashQuery, setSlashQuery] = useState("");
 70→  const [slashHighlight, setSlashHighlight] = useState(0);
 71→  const scrollRef = useRef<HTMLDivElement>(null);
 72→  const inputRef = useRef<HTMLInputElement>(null);
 73→
 74→  useEffect(() => {
 75→    scrollRef.current?.scrollTo({
 76→      top: scrollRef.current.scrollHeight,
 77→      behavior: "smooth",
 78→    });
 79→  }, [messages, rawMessages, showRaw]);
 80→
 81→  const displayItems = useMemo(() => condenseMessages(messages), [messages]);
 82→  const isActive = status === "connected" || status === "thinking";
 83→  const isArchived = status === "done" || status === "disconnected" || status === "error";
 84→
 85→  function handleSubmit(e: React.FormEvent) {
 86→    e.preventDefault();
 87→    const trimmed = input.trim();
 88→    if (!trimmed) return;
 89→
 90→    if (isActive) {
 91→      onSendMessage(trimmed);
 92→    } else {
 93→      onSpawnAgent(trimmed);
 94→    }
 95→    setInput("");
 96→    setShowSlashMenu(false);
 97→  }
 98→
 99→  function handleInputChange(e: React.ChangeEvent<HTMLInputElement>) {
100→    const value = e.target.value;
101→    setInput(value);
102→
103→    if (value.startsWith("/")) {
104→      setShowSlashMenu(true);
105→      setSlashQuery(value.slice(1));
106→      setSlashHighlight(0);
107→    } else {
108→      setShowSlashMenu(false);
109→      setSlashQuery("");
110→    }
111→  }
112→
113→  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
114→    if (!showSlashMenu) return;
115→    const filtered = filterCommands(slashQuery);
116→    if (filtered.length === 0) return;
117→
118→    if (e.key === "ArrowDown") {
119→      e.preventDefault();
120→      setSlashHighlight((i) => (i + 1) % filtered.length);
121→    } else if (e.key === "ArrowUp") {
122→      e.preventDefault();
123→      setSlashHighlight((i) => (i - 1 + filtered.length) % filtered.length);
124→    } else if (e.key === "Enter") {
125→      e.preventDefault();
126→      handleCommandSelect(filtered[slashHighlight]);
127→    } else if (e.key === "Escape") {
128→      e.preventDefault();
129→      setShowSlashMenu(false);
130→    } else if (e.key === "Tab") {
131→      e.preventDefault();
132→      setInput(`/${filtered[slashHighlight].name} `);
133→      setShowSlashMenu(false);
134→    }
135→  }
136→
137→  function handleCommandSelect(command: SlashCommand) {
138→    setShowSlashMenu(false);
139→    setSlashQuery("");
140→    setInput("");
141→
142→    if (command.clientSide) {
143→      if (command.name === "clear") {
144→        onClearHistory?.();
145→      }
146→      return;
147→    }
148→
149→    const commandText = `/${command.name}`;
150→    if (isActive) {
151→      onSendMessage(commandText);
152→    } else {
153→      onSpawnAgent(commandText);
154→    }
155→  }
156→
157→  return (
158→    <div className="flex h-full flex-col">
159→      <StatusBar
160→        connected={connected}
161→        status={status}
162→        showRaw={showRaw}
163→        onToggleRaw={() => setShowRaw((v) => !v)}
164→        showTasks={showTasks}
165→        onToggleTasks={onToggleTasks}
166→        showDiffs={showDiffs}
167→        onToggleDiffs={onToggleDiffs}
168→        onToggleSidebar={onToggleSidebar}
169→        onOpenSfxSettings={onOpenSfxSettings}
170→      />
171→
172→      <AgentSummary rawMessages={rawMessages} />
173→
174→      <div ref={scrollRef} className="flex-1 overflow-y-auto p-2 md:p-4 space-y-2">
175→        {loading ? (
176→          <div className="flex h-full flex-col items-center justify-center gap-3">
177→            <div className="flex gap-1">
178→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse" />
179→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:150ms]" />
180→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:300ms]" />
181→            </div>
182→            <span className="text-xs text-muted-foreground">
183→              {connected ? "Loading messages..." : "Connecting..."}
184→            </span>
185→          </div>
186→        ) : showRaw ? (
187→          rawMessages.length === 0 ? (
188→            <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
189→              No raw messages yet
190→            </div>
191→          ) : (
192→            <div className="space-y-1">
193→              {rawMessages.map((msg, i) => (
194→                <RawMessage key={i} message={msg} index={i} />
195→              ))}
196→            </div>
197→          )
198→        ) : (
199→          <>
200→            {messages.length === 0 && (
201→              <div className="flex h-full flex-col items-center justify-center gap-4 text-muted-foreground">
202→                <Terminal className="size-10 opacity-30" />
203→                <div className="text-center">
204→                  <p className="text-sm font-medium text-foreground/80">No agent selected</p>
205→                  <p className="mt-1 text-xs">Type a prompt below to spawn a Claude agent</p>
206→                </div>
207→                <div className="mt-2 grid grid-cols-2 gap-3 text-[11px]">
208→                  <div className="flex items-start gap-2 rounded-lg border p-3">
209→                    <MessageSquare className="mt-0.5 size-3.5 shrink-0 text-primary" />
210→                    <div>
211→                      <p className="font-medium text-foreground/80">Chat</p>
212→                      <p className="mt-0.5">Send prompts and review tool calls in real time</p>
213→                    </div>
214→                  </div>
215→                  <div className="flex items-start gap-2 rounded-lg border p-3">
216→                    <ListTodo className="mt-0.5 size-3.5 shrink-0 text-primary" />
217→                    <div>
218→                      <p className="font-medium text-foreground/80">Tasks</p>
219→                      <p className="mt-0.5">Track work with a kanban board and delegate to agents</p>
220→                    </div>
221→                  </div>
222→                </div>
223→              </div>
224→            )}
225→            {displayItems.map((item) => {
226→              if (item.kind === "condensed") {
227→                return <CondensedToolGroup key={item.id} group={item} />;
228→              }
229→              const msg = item.message;
230→              return msg.userQuestion ? (
231→                <UserQuestion
232→                  key={msg.id}
233→                  message={msg}
234→                  onRespond={onRespondToUserQuestion}
235→                />
236→              ) : msg.controlRequest ? (
237→                <ControlRequest
238→                  key={msg.id}
239→                  message={msg}
240→                  onRespond={onRespondToControl}
241→                />
242→              ) : (
243→                <Message key={msg.id} message={msg} />
244→              );
245→            })}
246→          </>
247→        )}
248→      </div>
249→
250→      {isArchived && messages.length > 0 ? (
251→        <div className="border-t px-4 py-2 text-center text-xs text-muted-foreground">
252→          This session has ended
253→        </div>
254→      ) : (
255→        <form
256→          onSubmit={handleSubmit}
257→          className="relative flex gap-2 border-t px-2 py-2 md:px-4 md:py-3"
258→        >
259→          {showSlashMenu && (
260→            <SlashCommandMenu
261→              query={slashQuery}
262→              highlightedIndex={slashHighlight}
263→              onSelect={handleCommandSelect}
264→              onHighlight={setSlashHighlight}
265→            />
266→          )}
267→          <input
268→            ref={inputRef}
269→            type="text"
270→            value={input}
271→            onChange={handleInputChange}
272→            onKeyDown={handleKeyDown}
273→            placeholder={isActive ? "Send a follow-up..." : "Enter a prompt to spawn agent..."}
274→            className="flex-1 rounded-md border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring"
275→          />
276→          <Button type="submit" disabled={!connected || !input.trim()}>
277→            {isActive ? "Send" : "Spawn"}
278→          </Button>
279→        </form>
280→      )}
281→    </div>
282→  );
283→}
284→
285→/** Badge color per Claude NDJSON message type. */
286→const TYPE_COLORS: Record<string, string> = {
287→  system: "text-yellow-500",
288→  assistant: "text-blue-400",
289→  result: "text-green-500",
290→  control_request: "text-orange-400",
291→  keep_alive: "text-muted-foreground",
292→};
293→
294→function RawMessage({ message, index }: { message: ClaudeMessage; index: number }) {
295→  const [expanded, setExpanded] = useState(false);
296→  const subtype = (message as { subtype?: string }).subtype;
297→  const typeLabel = subtype ? `${message.type}/${subtype}` : message.type;
298→  const colorClass = TYPE_COLORS[message.type] ?? "text-muted-foreground";
299→
300→  return (
301→    <div className="font-mono text-[11px] leading-relaxed">
302→      <button
303→        onClick={() => setExpanded((v) => !v)}
304→        className="flex w-full items-center gap-2 rounded px-2 py-1 text-left hover:bg-muted/50 transition-colors"
305→      >
306→        <span className="text-muted-foreground w-6 shrink-0 text-right">{index}</span>
307→        <span className={colorClass}>{typeLabel}</span>
308→        <span className="text-muted-foreground">{expanded ? "▼" : "▶"}</span>
309→      </button>
310→      {expanded && (
311→        <pre className="ml-10 overflow-x-auto rounded bg-muted/30 p-2 text-[10px] text-muted-foreground whitespace-pre-wrap break-all">
312→          {JSON.stringify(message, null, 2)}
313→        </pre>
314→      )}
315→    </div>
316→  );
317→}
