  3→/**
  4→ * Syntax-highlighted diff renderer for file-modifying tool calls.
  5→ *
  6→ * Uses `@pierre/diffs` (https://diffs.com) — a Shiki-based diff library
  7→ * that renders inside Shadow DOM for style isolation.
  8→ *
  9→ * ## Data flow
 10→ *
 11→ * When Claude calls Edit, Write, or MultiEdit, the tool_use content block
 12→ * contains the file path and before/after strings. These are preserved on
 13→ * {@link ToolCallInfo.input} by `relayChatMessage()` in `use-websocket.ts`.
 14→ * This component converts that input into `oldFile`/`newFile` objects that
 15→ * `MultiFileDiff` can render.
 16→ *
 17→ * ## Tool input shapes
 18→ *
 19→ * - **Edit** — `{ file_path, old_string, new_string }` — search/replace
 20→ *   on a single region. Renders as a diff of the changed fragment only
 21→ *   (not the full file, since we don't have full-file context).
 22→ *
 23→ * - **Write** — `{ file_path, content }` — create or overwrite a file.
 24→ *   Rendered as a "new file" diff with an empty old file.
 25→ *
 26→ * - **MultiEdit** — `{ file_path, edits: [{ old_string, new_string }] }` —
 27→ *   multiple search/replace ops on the same file. The individual hunks are
 28→ *   concatenated with `\n...\n` separators since we lack inter-hunk context.
 29→ *
 30→ * ## Size guard
 31→ *
 32→ * Diffs larger than 100 KB (combined old + new) are silently skipped to
 33→ * avoid freezing the browser on whole-file Write operations.
 34→ *
 35→ * ## Usage
 36→ *
 37→ * ```tsx
 38→ * <DiffViewer toolCall={toolCallInfo} />
 39→ * ```
 40→ *
 41→ * Renders nothing if the tool call has no input or isn't a file-modifying tool.
 42→ *
 43→ * Used by:
 44→ * - {@link CondensedToolGroup} — inline expandable diffs in collapsed view
 45→ * - {@link Message} — automatic diffs below standalone assistant messages
 46→ * - {@link DiffsPanel} — sidebar panel collecting all session diffs
 47→ */
 48→
 49→import { useMemo } from "react";
 50→import { MultiFileDiff } from "@pierre/diffs/react";
 51→import type { ToolCallInfo } from "@/lib/types";
 52→
 53→// ── Tool input type guards ──────────────────────────────────────────────
 54→
 55→/** Shape of the `input` object for the Claude Code `Edit` tool. */
 56→interface EditInput {
 57→  file_path: string;
 58→  old_string: string;
 59→  new_string: string;
 60→}
 61→
 62→/** Shape of the `input` object for the Claude Code `Write` tool. */
 63→interface WriteInput {
 64→  file_path: string;
 65→  content: string;
 66→}
 67→
 68→/** Shape of the `input` object for the Claude Code `MultiEdit` tool. */
 69→interface MultiEditInput {
 70→  file_path: string;
 71→  edits: Array<{ old_string: string; new_string: string }>;
 72→}
 73→
 74→/** Skip rendering for diffs exceeding this combined size (bytes). */
 75→const MAX_CONTENT_SIZE = 100_000;
 76→
 77→/**
 78→ * Build `{ oldFile, newFile }` from a tool call's raw input.
 79→ *
 80→ * Each tool has a different input shape — this function normalizes them
 81→ * into the `{ name, contents }` format that `MultiFileDiff` expects.
 82→ * Returns `null` when the tool call can't be rendered (wrong tool,
 83→ * missing fields, or content too large).
 84→ */
 85→function buildDiffFiles(tc: ToolCallInfo): {
 86→  oldFile: { name: string; contents: string };
 87→  newFile: { name: string; contents: string };
 88→} | null {
 89→  if (!tc.input) return null;
 90→
 91→  if (tc.name === "Edit") {
 92→    const input = tc.input as unknown as EditInput;
 93→    if (!input.file_path || input.old_string == null || input.new_string == null) return null;
 94→    if (input.old_string.length + input.new_string.length > MAX_CONTENT_SIZE) return null;
 95→    return {
 96→      oldFile: { name: input.file_path, contents: input.old_string },
 97→      newFile: { name: input.file_path, contents: input.new_string },
 98→    };
 99→  }
100→
101→  if (tc.name === "Write") {
102→    const input = tc.input as unknown as WriteInput;
103→    if (!input.file_path || input.content == null) return null;
104→    if (input.content.length > MAX_CONTENT_SIZE) return null;
105→    return {
106→      oldFile: { name: input.file_path, contents: "" },
107→      newFile: { name: input.file_path, contents: input.content },
108→    };
109→  }
110→
111→  if (tc.name === "MultiEdit") {
112→    const input = tc.input as unknown as MultiEditInput;
113→    if (!input.file_path || !Array.isArray(input.edits)) return null;
114→    const oldParts: string[] = [];
115→    const newParts: string[] = [];
116→    for (const edit of input.edits) {
117→      if (edit.old_string != null) oldParts.push(edit.old_string);
118→      if (edit.new_string != null) newParts.push(edit.new_string);
119→    }
120→    const oldContent = oldParts.join("\n...\n");
121→    const newContent = newParts.join("\n...\n");
122→    if (oldContent.length + newContent.length > MAX_CONTENT_SIZE) return null;
123→    return {
124→      oldFile: { name: input.file_path, contents: oldContent },
125→      newFile: { name: input.file_path, contents: newContent },
126→    };
127→  }
128→
129→  return null;
130→}
131→
132→/**
133→ * Renders a syntax-highlighted diff for a single file-modifying tool call.
134→ *
135→ * Accepts a {@link ToolCallInfo} with `input` data from Edit, Write, or
136→ * MultiEdit. Renders nothing if the tool call lacks input or the content
137→ * exceeds the size limit.
138→ *
139→ * The `themeType: "dark"` option is set explicitly because the dashboard
140→ * forces dark mode via CSS class rather than `prefers-color-scheme`, so
141→ * the library's automatic detection would pick the wrong theme.
142→ */
143→export function DiffViewer({ toolCall }: { toolCall: ToolCallInfo }) {
144→  const files = useMemo(() => buildDiffFiles(toolCall), [toolCall]);
145→
146→  if (!files) return null;
147→
148→  return (
149→    <div className="mt-1 overflow-hidden rounded-md border border-border">
150→      <MultiFileDiff
151→        oldFile={files.oldFile}
152→        newFile={files.newFile}
153→        options={{ themeType: "dark" }}
154→      />
155→    </div>
156→  );
157→}
